 bind('#new-folder',()=>modal('Create a folder',field('Folder name','name'),async f=>{await api('/api/folders','POST',{name:f.get('name')});await home()}));bind('#feedback',()=>modal('Feedback','<iframe title="SurveyMonkey feedback survey" src="/r/XRPXVQ2" style="width:100%;height:65vh;border:0"></iframe>',null))
