async function createStart(){member(`<main class="content"><h1>How would you like to create your survey?</h1><p class="muted">Start collecting feedback with a survey built for you.</p><section class="grid" style="margin-top:35px">${[['scratch','＋','Start from scratch','Create a survey your way.'],['ai','✧','Build with AI','Tell us what you want to learn.'],['templates','▦','Pick a popular template','Get a head start with expert-written questions.'],['paste','▤','Paste your questions','Turn your existing questions into a survey.'],['audience','◎','Find people to ask','Find the right audience for your survey.']].map(([id,icon,title,sub])=>`<button class="card card-action" data-start="${id}" style="display:block;text-align:left;min-height:200px"><div style="font-size:32px;color:#00a86b">${icon}</div><h2>${title}</h2><p class="muted">${sub}</p></button>`).join('')}</section></main>`);function launch(mode){if(mode==='templates'){location.href='/create/templates/';return}if(mode==='audience'){location.href='/mp/audience/';return}modal(mode==='ai'?'Build with AI':mode==='paste'?'Paste your questions':'Create a new survey',field('Survey title','title')+(mode==='paste'?'<label class="field"><span>Your questions (one per line)</span><textarea name="questions" required></textarea></label>':mode==='ai'?'<label class="field"><span>What would you like to learn?</span><textarea name="prompt" placeholder="Describe your survey goal" required></textarea></label><p class="muted">Creates a local starter survey from your topic. Review and edit the questions before publishing.</p>':''),async f=>{let questions=[];if(mode==='paste')questions=String(f.get('questions')).split('\n').filter(x=>x.trim()).map(title=>({title,kind:'comment'}));if(mode==='ai'){const topic=String(f.get('prompt')).trim();questions=[{title:`How would you rate your experience with ${topic}?`,kind:'star_rating'},{title:'What worked well for you?',kind:'comment'},{title:'What could we improve?',kind:'comment'},{title:'How likely are you to recommend us?',kind:'nps'}]}const s=await api('/api/surveys','POST',{title:f.get('title'),questions});location.href='/create/?sm='+s.id},'Create survey')}bind('[data-start]',(_,el)=>launch(el.dataset.start));if(params.get('mode')){launch(params.get('mode'));if(params.get('idea')&&$('textarea[name=prompt]'))$('textarea[name=prompt]').value=params.get('idea')}}
function surveyNav(active){return `<section class="editor-head"><div class="row spread" style="padding-bottom:16px"><div class="row"><span class="pill">${E(survey.status)}</span><button class="editor-title" id="rename-title">${E(survey.title)} ✎</button></div><div class="row"><button class="small" id="survey-comments">Comments</button><a class="button small" href="/authoring/preview?sm=${survey.id}">Preview survey</a></div></div><nav class="tabs">${[['Design survey','/create/?sm='],['Publish survey','/collect/'],['Connect apps','/create/connect?sm='],['Analyze results','/analyze/']].map(([name,url])=>`<a class="${name===active?'active':''}" href="${url}${survey.id}${url.endsWith('/')?'/':''}">${name}</a>`).join('')}</nav></section>`}
function renameEvent(){bind('#survey-comments',comments);bind('#rename-title',()=>modal('Edit survey title',field('Survey title','title',survey.title)+`<label class="field"><span>Description</span><textarea name="description">${E(survey.description)}</textarea></label>`,async f=>{survey=await api('/api/surveys/'+survey.id,'PATCH',Object.fromEntries(f));await editor()}))}
function choiceItems(q){return q.choices.map(c=>typeof c==='string'?{id:c,label:c}:c)}
function questionInput(q,preview=false){let choices=choiceItems(q),name='q-'+q.id,kind=q.kind,val=answers[q.id];const checked=v=>String(val)===String(v)?'checked':'';if(['multiple_choice','checkboxes','image_choice'].includes(kind))return choices.map(c=>`<label class="choice"><input type="${kind==='checkboxes'?'checkbox':'radio'}" name="${name}" value="${E(c.id)}" data-other-choice="${c.label===q.options.other_label?'true':'false'}" data-exclusive="${q.options.exclusive_labels?.includes(c.label)?'true':'false'}" ${kind==='checkboxes'?(val||[]).includes(c.id)?'checked':'':checked(c.id)}>${E(c.label)}</label>`).join('')+(q.options.other_label?`<label class="field"><span>${E(q.options.other_label)}</span><input name="${name}-other" data-other-for="${name}" value="${E(answers[q.id+'__other']||'')}" ${choices.some(c=>c.label===q.options.other_label&&(Array.isArray(val)?val.includes(c.id):val===c.id))?'':'disabled'}></label>`:'');if(kind==='dropdown')return `<select data-question="${q.id}" name="${name}"><option value="">Select an answer</option>${choices.map(c=>`<option value="${E(c.id)}" ${val===c.id?'selected':''}>${E(c.label)}</option>`).join('')}</select>`;if(['star_rating','nps'].includes(kind)){const min=kind==='nps'?0:1,max=kind==='nps'?10:Number(q.options.max||5);return `<div class="rating">${Array.from({length:Math.min(20,max-min+1)},(_,i)=>i+min).map(n=>`<label><input type="radio" name="${name}" value="${n}" ${checked(n)}>${kind==='star_rating'?'★ '+n:n}</label>`).join('')}</div>`}if(kind==='slider')return `<div class="row"><span>${q.options.min||0}</span><input type="range" name="${name}" min="${q.options.min||0}" max="${q.options.max||100}" value="${val??50}"><output>${val??50}</output><span>${q.options.max||100}</span></div>`;if(kind==='comment')return `<textarea name="${name}" style="width:100%" aria-label="${E(q.title)}">${E(val||'')}</textarea>`;if(kind==='text')return `<p>${E(q.options.body||'')}</p>`;if(kind==='image')return (q.options.url?.startsWith('/static/')||q.options.url?.startsWith('/api/media/'))?`<img src="${E(q.options.url)}" alt="${E(q.title)}" style="max-width:100%">`:'<p class="muted">Add an image in the question settings.</p>';if(kind==='file')return `<input type="file" name="${name}" aria-label="${E(q.title)}"><p class="muted">PNG, JPG, WEBP, GIF, PDF, TXT or CSV · Up to 5 MB</p>`;if(['matrix','matrix_dropdown'].includes(kind)){const rows=q.options.rows||['Row 1','Row 2'],cols=choices.length?choices:[{id:'1',label:'Disagree'},{id:'2',label:'Neutral'},{id:'3',label:'Agree'}];return `<table class="matrix"><thead><tr><th></th>${cols.map(c=>`<th>${E(c.label)}</th>`).join('')}</tr></thead><tbody>${rows.map((row,i)=>`<tr><td>${E(row)}</td>${kind==='matrix_dropdown'?`<td colspan="${cols.length}"><select data-matrix="${q.id}" data-row="${i}" name="${name}-${i}" aria-label="${E(row)}"><option value="">Choose an answer</option>${cols.map(c=>`<option value="${E(c.id)}" ${String(val?.[i])===c.id?'selected':''}>${E(c.label)}</option>`).join('')}</select></td>`:cols.map(c=>`<td><input type="radio" data-matrix="${q.id}" data-row="${i}" name="${name}-${i}" value="${E(c.id)}" ${String(val?.[i])===c.id?'checked':''} aria-label="${E(row+' '+c.label)}"></td>`).join('')}</tr>`).join('')}</tbody></table>`}if(['contact','multiple_text'].includes(kind)){const rows=kind==='contact'?['Name','Company','Address','City','State','ZIP','Country','Email','Phone']:q.options.rows||['Field 1','Field 2'];return rows.map((row,i)=>`<label class="field"><span>${E(row)}</span><input data-matrix="${q.id}" data-row="${i}" name="${name}-${i}" value="${E(val?.[i]||'')}"></label>`).join('')}if(kind==='ranking')return choices.map((c,i)=>`<label class="choice"><select name="${name}" data-rank="${c.id}">${choices.map((_,n)=>`<option value="${n}" ${n===(val?val.indexOf(c.id):i)?'selected':''}>${n+1}</option>`).join('')}</select>${E(c.label)}</label>`).join('');if(kind==='best_worst')return `<p class="muted">Choose your best and worst options.</p>${['Best','Worst'].map((label,i)=>`<label class="field"><span>${label}</span><select name="${name}" data-best="${i}"><option value="">Select</option>${choices.map(c=>`<option value="${E(c.id)}" ${val?.[i]===c.id?'selected':''}>${E(c.label)}</option>`).join('')}</select></label>`).join('')}`;return `<input style="width:100%" name="${name}" aria-label="${E(q.title)}" type="${kind==='date'?'date':q.options.validation==='email'?'email':'text'}" value="${E(val||'')}">`}
function bindOtherAnswers(){bind('[data-other-choice]',(_,el)=>{const siblings=$$(`input[name="${el.name}"]`);if(el.type==='checkbox'&&el.checked){siblings.forEach(other=>{if(other!==el&&(el.dataset.exclusive==='true'||other.dataset.exclusive==='true'))other.checked=false})}const field=$(`[data-other-for="${el.name}"]`);if(field){field.disabled=!siblings.some(e=>e.checked&&e.dataset.otherChoice==='true');if(!field.disabled)field.focus()}},'change')}
async function editor(){if(!survey)survey=await api('/api/surveys/'+sid);member(surveyNav('Design survey')+`<div class="editor-layout"><aside class="builder-sidebar"><div class="row" style="flex-wrap:wrap">${['Build','Style','Logic','Options'].map(x=>`<button class="${side===x?'primary':''}" data-side="${x}" style="width:auto">${x}</button>`).join('')}</div><div id="side-content"></div></aside><main class="survey-canvas"><div class="row spread" style="margin-bottom:18px"><span class="muted">All changes saved</span><a href="/authoring/preview?sm=${survey.id}">Preview ▷</a></div>${survey.pages.map((p,pi)=>`<section class="survey-paper" style="--survey-color:${E(survey.theme.color||'#00bf6f')}">${pi===0?`<h1>${E(survey.title)}</h1>${survey.description?`<p style="padding:20px 35px">${E(survey.description)}</p>`:''}`:''}<div class="page-heading row spread"><span>Page ${pi+1}${p.title?' — '+E(p.title):''}</span><div><button class="small link" data-page="${p.id}">Edit page</button>${survey.pages.length>1?`<button class="small link danger" data-delete-page="${p.id}">Delete</button>`:''}</div></div>${p.questions.map((q,qi)=>`<article class="question" data-qid="${q.id}"><h3>${q.required?'* ':''}${survey.pages.slice(0,pi).reduce((count,p)=>count+p.questions.length,0)+qi+1}. ${E(q.title)}</h3><div style="pointer-events:none">${questionInput(q)}</div><div class="question-actions"><button data-edit="${q.id}">Edit</button><button data-copy="${q.id}">Copy</button><button data-move="${q.id}" data-direction="-1">↑</button><button data-move="${q.id}" data-direction="1">↓</button><button data-delete="${q.id}">Delete</button></div></article>`).join('')}<div class="page-footer"><button data-add="${p.id}">＋ Add question</button></div></section>`).join('')}<button id="add-page">＋ New page</button></main></div>`);renameEvent();bind('[data-side]',(_,el)=>{side=el.dataset.side;renderSide()});renderSide();bind('[data-add]',(_,el)=>editQuestion(null,el.dataset.add));bind('[data-edit]',(_,el)=>editQuestion(findQ(el.dataset.edit)));bind('[data-copy]',async(_,el)=>{const q=findQ(el.dataset.copy);survey=await api('/api/surveys/'+survey.id+'/questions','POST',q);await editor()});bind('[data-delete]',(_,el)=>modal('Delete question?','<p>This removes the question from your survey.</p>',async()=>{survey=await api(`/api/surveys/${survey.id}/questions/${el.dataset.delete}`,'DELETE');await editor()},'Delete'));bind('[data-move]',async(_,el)=>{const pages=survey.pages.map(p=>({id:p.id,questions:p.questions.map(q=>q.id)}));const p=pages.find(p=>p.questions.includes(el.dataset.move)),i=p.questions.indexOf(el.dataset.move),j=i+Number(el.dataset.direction);if(j<0||j>=p.questions.length)return;[p.questions[i],p.questions[j]]=[p.questions[j],p.questions[i]];survey=await api('/api/surveys/'+survey.id+'/reorder','POST',{pages});await editor()});bind('#add-page',async()=>{survey=await api('/api/surveys/'+survey.id+'/pages','POST',{});await editor()});bind('[data-page]',(_,el)=>{const p=survey.pages.find(p=>p.id===el.dataset.page);modal('Edit page',field('Page title','title',p.title,'text',false)+`<label class="field"><span>Description</span><textarea name="description">${E(p.description)}</textarea></label>`,async f=>{survey=await api(`/api/surveys/${survey.id}/pages/${p.id}`,'PATCH',Object.fromEntries(f));await editor()})});bind('[data-delete-page]',(_,el)=>modal('Delete page?','<p>All questions on this page will also be removed.</p>',async()=>{survey=await api(`/api/surveys/${survey.id}/pages/${el.dataset.deletePage}`,'DELETE');await editor()},'Delete page'))}
function findQ(id){return survey.pages.flatMap(p=>p.questions).find(q=>q.id===id)}
function renderSide(){const el=$('#side-content');if(side==='Build'){el.innerHTML='<h3>QUESTION TYPES</h3>'+Object.entries(kinds).map(([key,label])=>`<button data-kind="${key}">＋ ${label}</button>`).join('');bind('[data-kind]',(_,b)=>editQuestion(null,survey.pages.at(-1).id,b.dataset.kind))}else if(side==='Style'){el.innerHTML='<h3>THEMES</h3>'+[['Catalyst','#00bf6f'],['Heritage','#006b54'],['Simple','#48535b'],['Full Color','#8457bc'],['Highrise','#007faa'],['Dewdrop','#239ca2'],['Pastel','#9c78a9'],['Walnut','#785c44'],['Stone','#68757b'],['Porch Lights','#ba7b23'],['Scribble','#333e48'],['Arctic','#3d8eb1']].map(([name,color])=>`<button data-theme="${color}" style="border-left:12px solid ${color}">${name}</button>`).join('');bind('[data-theme]',async(_,b)=>{survey=await api('/api/surveys/'+survey.id,'PATCH',{theme:{color:b.dataset.theme,name:b.textContent}});await editor()})}else if(side==='Logic'){el.innerHTML='<h3>Skip logic</h3><p class="muted">Send respondents to a different page based on their answer. Select a choice question to edit its skip logic.</p>'+survey.pages.flatMap(p=>p.questions).filter(q=>['multiple_choice','dropdown'].includes(q.kind)).map(q=>`<button data-logic="${q.id}">${E(q.title)}</button>`).join('');bind('[data-logic]',(_,b)=>{const q=findQ(b.dataset.logic);modal('Question skip logic',choiceItems(q).map(c=>`<label class="field"><span>${E(c.label)}</span><select name="${c.id}"><option value="">Next page</option>${survey.pages.map((p,i)=>`<option value="${p.id}" ${q.options.skip?.[c.id]===p.id?'selected':''}>Page ${i+1}: ${E(p.title)}</option>`).join('')}<option value="end" ${q.options.skip?.[c.id]==='end'?'selected':''}>End of survey</option></select></label>`).join(''),async f=>{q.options.skip=Object.fromEntries([...f].filter(([,v])=>v));survey=await api(`/api/surveys/${survey.id}/questions/${q.id}`,'PUT',q);await editor()})})}else{el.innerHTML='<h3>SURVEY OPTIONS</h3><button id="survey-settings">Survey settings</button>';bind('#survey-settings',()=>modal('Survey settings',field('Thank you message','thank_you',survey.settings.thank_you||'Thank you for completing this survey.')+`<label class="choice"><input name="progress" type="checkbox" ${survey.settings.progress?'checked':''}>Show progress bar</label><label class="choice"><input name="back" type="checkbox" ${survey.settings.back!==false?'checked':''}>Allow previous page</label>`,async f=>{survey=await api('/api/surveys/'+survey.id,'PATCH',{settings:{...survey.settings,thank_you:f.get('thank_you'),progress:f.has('progress'),back:f.has('back')}});toast('Settings saved')}))}}
function editQuestion(q,pageId,kind='multiple_choice'){const current=q||{title:'',kind,choices:[],required:false,options:{},page_id:pageId};modal(q?'Edit question':'Add question',`<label class="field"><span>Question type</span><select name="kind">${Object.entries(kinds).map(([key,label])=>`<option value="${key}" ${current.kind===key?'selected':''}>${label}</option>`).join('')}</select></label>${field('Question','title',current.title)}<label class="field"><span>Answer choices (one per line)</span><textarea name="choices" placeholder="Choice 1&#10;Choice 2">${E(choiceItems(current).map(c=>c.label).join('\n'))}</textarea></label><label class="field"><span>Rows / fields (one per line, for matrix and multiple textboxes)</span><textarea name="rows">${E((current.options.rows||[]).join('\n'))}</textarea></label><label class="choice"><input name="required" type="checkbox" ${current.required?'checked':''}>Require an answer to this question</label><label class="field"><span>Page</span><select name="page_id">${survey.pages.map((p,i)=>`<option value="${p.id}" ${current.page_id===p.id?'selected':''}>Page ${i+1}</option>`).join('')}</select></label><label class="field"><span>Image (for image questions)</span><input name="image" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></label><label class="field"><span>Text content / description</span><textarea name="body">${E(current.options.body||'')}</textarea></label><div class="row">${field('Minimum','min',current.options.min??0,'number',false)}${field('Maximum','max',current.options.max??(current.kind==='slider'?100:5),'number',false)}</div>`,async f=>{const old=choiceItems(current),values=String(f.get('choices')).split('\n').map(x=>x.trim()).filter(Boolean).map((label,i)=>({label,id:old.find(c=>c.label===label)?.id||old[i]?.id||crypto.randomUUID()}));let options={...current.options,body:f.get('body')};if(f.get('image')?.size){const upload=new FormData();upload.append('file',f.get('image'));const response=await fetch('/api/surveys/'+survey.id+'/media',{method:'POST',headers:{'X-CSRF-Token':session.csrf},body:upload});const result=await response.json();if(!response.ok)throw new Error(result.detail);options.url=result.url}const rows=String(f.get('rows')).split('\n').filter(x=>x.trim());if(rows.length)options.rows=rows;if(['star_rating','slider'].includes(f.get('kind'))){options.min=Number(f.get('min'));options.max=Number(f.get('max'))}const payload={kind:f.get('kind'),title:f.get('title'),choices:values,required:f.has('required'),page_id:f.get('page_id'),options};survey=await api('/api/surveys/'+survey.id+'/questions'+(q?'/'+q.id:''),q?'PUT':'POST',payload);await editor()},'Save question')}
async function collect(){survey=await api('/api/surveys/'+sid);const data=await api(`/api/surveys/${sid}/collectors`);member(surveyNav('Publish survey')+`<main class="content"><h1>Ready to publish?</h1><p class="muted">Choose how you want to collect responses.</p><div class="grid">${[['weblink','Share a link','Get a link to share anywhere'],['email','Send by email','Create a link for your email invitation'],['website','Embed on a website','Add your survey to your website'],['manual','Manual data entry','Enter responses yourself'],['kiosk','Kiosk survey','Collect responses on a shared device']].map(([key,title,description])=>`<button data-collector="${key}" class="card card-action" style="display:block;text-align:left"><h3>${title}</h3><p class="muted">${description}</p></button>`).join('')}</div><h2 style="margin-top:40px">Your collectors</h2>${data.collectors.length?data.collectors.map(c=>`<article class="card survey-card"><div class="grow"><h3>${E(c.name)}</h3><p class="muted">${c.response_count} responses · <span class="pill">${c.status}</span></p><a href="/r/${c.token}">${location.origin}/r/${c.token}</a></div><button data-link="${c.token}">Copy link</button><button data-toggle="${c.id}" data-status="${c.status==='open'?'closed':'open'}">${c.status==='open'?'Close':'Reopen'} collector</button><button data-rename-collector="${c.id}">Edit</button></article>`).join(''):'<div class="empty">No collectors yet. Choose a method above to publish your survey.</div>'}</main>`);renameEvent();bind('[data-collector]',(_,el)=>modal('Create collector',field('Collector name','name',{weblink:'Web link',email:'Email invitation',website:'Website',manual:'Manual data entry',kiosk:'Kiosk'}[el.dataset.collector]),async f=>{await api(`/api/surveys/${sid}/collectors`,'POST',{name:f.get('name'),kind:el.dataset.collector});await collect()},'Publish survey'));bind('[data-link]',async(_,el)=>{await navigator.clipboard.writeText(location.origin+'/r/'+el.dataset.link);toast('Survey link copied')});bind('[data-toggle]',async(_,el)=>{await api(`/api/surveys/${sid}/collectors/${el.dataset.toggle}`,'PATCH',{status:el.dataset.status});await collect()});bind('[data-rename-collector]',(_,el)=>{const c=data.collectors.find(c=>c.id===el.dataset.renameCollector);modal('Collector settings',field('Name','name',c.name),async f=>{await api(`/api/surveys/${sid}/collectors/${c.id}`,'PATCH',{name:f.get('name')});await collect()})})}
async function readAnswers(preview=false){const p=survey.pages[pageIndex];for(const q of p.questions){const els=$$(`[name="q-${q.id}"]`),matrix=$$(`[data-matrix="${q.id}"]`);if(matrix.length){answers[q.id]={};matrix.forEach(el=>{if(el.type!=='radio'||el.checked)if(el.value)answers[q.id][el.dataset.row]=el.value});continue}if(['text','image'].includes(q.kind))continue;if(q.options.other_label){const other=$(`[data-other-for="q-${q.id}"]`);if(other&&!other.disabled)answers[q.id+'__other']=other.value;else delete answers[q.id+'__other']}if(q.kind==='checkboxes')answers[q.id]=els.filter(x=>x.checked).map(x=>x.value);else if(q.kind==='ranking')answers[q.id]=els.sort((a,b)=>Number(a.value)-Number(b.value)).map(x=>x.dataset.rank);else if(q.kind==='best_worst')answers[q.id]=els.map(x=>x.value).filter(Boolean);else if(['multiple_choice','image_choice','star_rating','nps'].includes(q.kind))answers[q.id]=els.find(x=>x.checked)?.value||'';else if(q.kind==='file'){if(els[0]?.files?.length){if(preview){answers[q.id]='preview-file';continue}const data=new FormData();data.append('file',els[0].files[0]);const r=await fetch('/api/respond/'+path.split('/')[2]+'/files',{method:'POST',headers:{'X-CSRF-Token':session.csrf},body:data});const upload=await r.json();if(!r.ok)throw new Error(upload.detail);answers[q.id]=upload.id}}else answers[q.id]=els[0]?.value||''}}
async function respondent(preview=false){if(!survey){if(preview)survey=await api('/api/surveys/'+sid);else survey=(await api('/api/respond/'+path.split('/')[2])).survey}const p=survey.pages[pageIndex];$('#app').innerHTML=(preview?`<div class="preview-toolbar row"><a class="brand" href="/home/">SurveyMonkey</a><span class="grow"></span><button data-device="860">Desktop</button><button data-device="600">Tablet</button><button data-device="390">Mobile</button><a class="button" href="/create/?sm=${survey.id}">Edit survey</a><a class="button primary" href="/collect/${survey.id}/">Continue</a></div><p class="muted" style="text-align:center">Preview mode — your answers will not be saved.</p>`:'')+`<main class="respondent"><form id="response-form"><section class="survey-paper" style="--survey-color:${E(survey.theme.color||'#00bf6f')}"><h1>${E(survey.title)}</h1>${survey.description?`<p class="question">${E(survey.description)}</p>`:''}${p.title||p.description?`<div class="page-heading"><h2>${E(p.title)}</h2><p>${E(p.description)}</p></div>`:''}${survey.settings.progress?`<progress max="${survey.pages.length}" value="${pageIndex+1}" style="width:100%"></progress>`:''}${p.questions.map((q,i)=>`<section class="question"><h3>${q.required?'* ':''}${survey.pages.slice(0,pageIndex).reduce((count,p)=>count+p.questions.length,0)+i+1}. ${E(q.title)}</h3>${questionInput(q,true)}<p class="error" id="error-${q.id}"></p></section>`).join('')}<div class="page-footer">${historyPages.length&&survey.settings.back!==false?'<button id="previous" type="button">Prev</button>':''}<button class="primary" type="submit">${pageIndex===survey.pages.length-1?'Done':'Next'}</button></div></section></form><footer class="app-footer">Powered by <a class="brand" style="font-size:18px" href="/">SurveyMonkey</a></footer></main>`;bindOtherAnswers();bind('[data-device]',(_,el)=>$('.respondent').style.maxWidth=el.dataset.device+'px');bind('#previous',async()=>{await readAnswers(preview);pageIndex=historyPages.pop();await respondent(preview)});bind('input[type=range]',(_,el)=>el.nextElementSibling.value=el.value,'input');$('#response-form').onsubmit=async e=>{e.preventDefault();try{await readAnswers(preview);let errors=false;for(const q of p.questions){const v=answers[q.id];const missing=q.required&&!['text','image'].includes(q.kind)&&(v===undefined||v===''||Array.isArray(v)&&!v.length||typeof v==='object'&&!Object.keys(v).length);$('#error-'+q.id).textContent=missing?'This question requires an answer.':'';if(missing)errors=true}if(errors)return;let next=pageIndex+1;for(const q of p.questions){const target=q.options.skip?.[answers[q.id]];if(target){next=target==='end'?survey.pages.length:survey.pages.findIndex(p=>p.id===target);break}}if(next<survey.pages.length&&next>=0){if(historyPages.includes(next)||next===pageIndex)throw new Error('This survey contains a loop in its skip logic. Please contact the survey owner.');historyPages.push(pageIndex);pageIndex=next;await respondent(preview);window.scrollTo(0,0);return}if(!preview)await api('/api/respond/'+path.split('/')[2],'POST',{answers,submission_key:submissionKey});$('.respondent').innerHTML=`<div class="survey-paper"><h1>${E(survey.title)}</h1><div class="empty"><h2>${E(survey.settings.thank_you||'Thank you for completing this survey.')}</h2>${preview?'<p>Your preview answers were not recorded.</p><button id="restart-preview">Restart preview</button>':''}</div></div>`;bind('#restart-preview',async()=>{answers={};pageIndex=0;historyPages=[];await respondent(true)})}catch(err){if(err.fields){const target=survey.pages.findIndex(p=>p.questions.some(q=>err.fields[q.id]));if(target>=0&&target!==pageIndex){pageIndex=target;historyPages=historyPages.filter(i=>i<target);await respondent(preview)}for(const [qid,msg]of Object.entries(err.fields))if($('#error-'+qid))$('#error-'+qid).textContent=msg;$('.error:not(:empty)')?.scrollIntoView({block:'center'})}toast(err.message)}}}
async function analyze(){const [data,views]=await Promise.all([api(`/api/surveys/${sid}/results?`+new URLSearchParams(analysisFilters)),api(`/api/surveys/${sid}/views`)]);survey=data.survey;member(surveyNav('Analyze results')+`<main class="content"><div class="row spread"><nav class="tabs">${['Question summaries','Individual responses','Dashboards'].map(x=>`<button data-analysis="${x}" class="${analysisTab===x?'active':''}">${x}</button>`).join('')}</nav><a class="button" href="/api/surveys/${sid}/export.csv?${E(new URLSearchParams(analysisFilters))}">Export CSV</a></div><div class="toolbar"><button id="filter-results">Filter</button><button id="save-view">Save as view</button><select id="saved-view" aria-label="Saved views"><option value="">Saved views</option>${views.views.map(v=>`<option value="${v.id}">${E(v.name)}</option>`).join('')}</select>${Object.keys(analysisFilters).length?'<button id="clear-filters">Clear filters</button>':''}<span class="muted">${data.total} of ${data.total_unfiltered} responses</span></div><div class="stats"><div class="card">TOTAL RESPONSES<strong>${data.total}</strong></div><div class="card">COMPLETE RESPONSES<strong>${data.total}</strong></div><div class="card">QUESTIONS<strong>${data.questions.length}</strong></div></div><section id="analysis-body"></section></main>`);renameEvent();bind('[data-analysis]',async(_,el)=>{analysisTab=el.dataset.analysis;await analyze()});bind('#filter-results',()=>filterResults());bind('#clear-filters',async()=>{analysisFilters={};await analyze()});bind('#save-view',()=>modal('Save view',field('View name','name'),async f=>{await api(`/api/surveys/${sid}/views`,'POST',{name:f.get('name'),filters:analysisFilters});await analyze()}));bind('#saved-view',async(_,el)=>{const view=views.views.find(v=>v.id===el.value);if(view){analysisFilters=view.filters;await analyze()}},'change');const body=$('#analysis-body');if(!data.total){body.innerHTML='<div class="empty"><h2>No responses yet</h2><p>Once you collect responses, your results will appear here.</p><a class="button primary" href="/collect/'+sid+'/">Collect responses</a></div>';return}if(analysisTab==='Individual responses'){body.innerHTML=data.responses.map((r,i)=>`<article class="card" style="margin-bottom:20px"><div class="row spread"><h2>Respondent ${data.total-i}</h2><button class="small danger" data-delete-response="${r.id}">Delete response</button></div><p class="muted">Completed ${new Date(r.completed*1000).toLocaleString()}</p>${data.questions.map(({question:q})=>{let v=r.answers[q.id];const labels=Object.fromEntries(choiceItems(q).map(c=>[c.id,c.label]));if(q.kind==='file'&&v)return `<h3>${E(q.title)}</h3><p><a class="button" href="/api/media/${encodeURIComponent(v)}" download>Download attachment</a></p>`;return `<h3>${E(q.title)}</h3><p>${E(Array.isArray(v)?v.map(x=>labels[x]||x).join(', '):typeof v==='object'?JSON.stringify(v):labels[v]??v??'Skipped')}${r.answers[q.id+'__other']?': '+E(r.answers[q.id+'__other']):''}</p>`}).join('')}</article>`).join('');bind('[data-delete-response]',(_,el)=>modal('Delete response?','<p>This permanently removes the response from this survey.</p>',async()=>{await api(`/api/surveys/${sid}/responses/${el.dataset.deleteResponse}`,'DELETE');await analyze()},'Delete'));return}body.innerHTML=data.questions.map((r,i)=>{const q=r.question,labels=Object.fromEntries(choiceItems(q).map(c=>[c.id,c.label]));return `<article class="card" style="margin-bottom:24px"><h3>Q${i+1}: ${E(q.title)}</h3><p class="muted">Answered: ${r.answered} &nbsp; Skipped: ${r.skipped}${r.nps?` &nbsp; NPS: ${r.nps.score===null?'—':r.nps.score} · Promoters: ${r.nps.promoters} · Passives: ${r.nps.passives} · Detractors: ${r.nps.detractors}`:r.average!==null?' &nbsp; Average: '+r.average.toFixed(2):''}</p><div class="result-chart">${Object.entries(r.counts).map(([value,count])=>`<div class="bar-row"><span>${E(labels[value]||value)}</span><div class="bar"><span style="width:${count/Math.max(1,r.answered)*100}%"></span></div><span>${count} (${Math.round(count/Math.max(1,r.answered)*100)}%)</span></div>`).join('')}</div></article>`}).join('')}
