async function checkout(){const data=await api('/api/billing/plans');let plan=params.get('plan')||'team-advantage';if(!data.plans[plan])plan='team-advantage';member(`<main class="content" style="max-width:800px"><h1>Upgrade your plan</h1><p class="notice">Local payment sandbox. No real card details are needed and no charge will be made.</p><form id="checkout-form" class="card"><label class="field"><span>Plan</span><select name="plan">${Object.entries(data.plans).map(([key,p])=>`<option value="${key}" ${key===plan?'selected':''}>${p.name} — CA$${p.monthly_minor/100} per user / month (${p.period===1?'monthly':'annual'} billing)</option>`).join('')}</select></label>${field('Number of users','users',3,'number')}<p class="muted" id="billing-period">Minimum 3 users. Billed annually.</p><h2 id="checkout-total"></h2><label class="field"><span>Sandbox payment result</span><select name="scenario">${data.scenarios.map(s=>`<option value="${s.id}">${E(s.display_label)}</option>`).join('')}</select></label><p id="checkout-error" class="error"></p><button class="primary" type="submit">Confirm simulated purchase</button></form></main>`);const form=$('#checkout-form');function total(){const p=data.plans[form.elements.plan.value],n=Number(form.elements.users.value);$('#checkout-total').textContent=(p.period===1?'Monthly':'Annual')+' total: CA$'+(p.monthly_minor/100*n*p.period).toLocaleString();$('#billing-period').textContent='Minimum 3 users. Billed '+(p.period===1?'monthly.':'annually.')}form.oninput=total;total();form.onsubmit=async e=>{e.preventDefault();const button=$('button[type=submit]',form);button.disabled=true;try{const f=new FormData(form);const flow=await api('/api/billing/intent','POST',{plan:f.get('plan'),users:Number(f.get('users')),key:crypto.randomUUID()});const result=await api('/api/billing/attempt','POST',{flow_id:flow.flow_id,scenario:f.get('scenario'),key:crypto.randomUUID()});if(['APPROVED','CONSUMED'].includes(result.status)){toast('Your local plan has been upgraded');location.href='/account/billing/'}else{$('#checkout-error').textContent=result.status==='DECLINED'?'The simulated payment was declined. Choose another result and try again.':'The simulated payment needs a retry.'}}catch(err){$('#checkout-error').textContent=err.message}finally{button.disabled=false}}}

function filterResults(){const questions=survey.pages.flatMap(p=>p.questions);modal('Filter responses',`<label class="field"><span>Question</span><select name="question" id="filter-question"><option value="">Any question</option>${questions.map(q=>`<option value="${q.id}" ${analysisFilters.question===q.id?'selected':''}>${E(q.title)}</option>`).join('')}</select></label><label class="field"><span>Answer</span><span id="filter-answer-container"></span></label><div class="row">${field('From','from',analysisFilters.from||'','date',false)}${field('To','to',analysisFilters.to||'','date',false)}</div>`,async f=>{analysisFilters=Object.fromEntries([...f].filter(([,v])=>v));await analyze()},'Apply filter');function choices(){const q=questions.find(q=>q.id===$('#filter-question').value);$('#filter-answer-container').innerHTML=q?.choices.length?`<select name="answer"><option value="">Any answer</option>${choiceItems(q).map(c=>`<option value="${E(c.id)}" ${analysisFilters.answer===c.id?'selected':''}>${E(c.label)}</option>`).join('')}</select>`:`<input name="answer" value="${E(analysisFilters.answer||'')}" placeholder="Exact answer">`}choices();bind('#filter-question',choices,'change')}

async function openTemplate(t){
 if(!t)return;
 if(location.pathname.startsWith('/create/templates'))history.replaceState(null,'','/create/templates/'+encodeURIComponent(t.template_id));
 if(t.boundary){modal(t.title,`<p>${E(t.description)}</p><p>This template is outside the currently implemented local detail set.</p><a class="button" href="/create/templates/">Back to template collection</a>`,null);return}
 const pages=t.pages||[{title:'',questions:t.questions}];let current=0;
 modal(t.title,(t.captured_only?'<p class="notice">This preview includes the available first page. Additional template pages have not been captured yet.</p>':'')+'<p class="muted">Preview answers are not recorded.</p><section id="template-preview-content"></section><div id="template-preview-navigation" class="row spread"></div>',async()=>{const survey=await api('/api/surveys','POST',{title:t.title,description:t.survey_description||'',...(t.pages?{pages:t.pages}:{questions:t.questions})});location.href='/create/?sm='+survey.id},'Use this template');
 function show(){const page=pages[current],offset=pages.slice(0,current).reduce((sum,p)=>sum+p.questions.length,0);$('#template-preview-content').innerHTML=(page.title?`<h3>${E(page.title)}</h3>`:'')+page.questions.map((q,i)=>`<section class="question"><h4>${q.required?'* ':''}${offset+i+1}. ${E(q.title)}</h4>${questionInput({...q,id:'template-'+current+'-'+i})}</section>`).join('');$('#template-preview-navigation').innerHTML=pages.length>1?`<button id="template-prev" type="button" ${current===0?'disabled':''}>Previous page</button><span role="status">Page ${current+1} of ${pages.length}</span><button id="template-next" type="button" ${current===pages.length-1?'disabled':''}>Next page</button>`:'';bind('#template-prev',()=>{current--;show()});bind('#template-next',()=>{current++;show()});bindOtherAnswers()}
 show()
}
async function setupHomeTemplates(){
 const tabs=[$('#home-idea-tab'),$('#home-template-tab')];if(!tabs[0])return;
 let catalog;async function show(index){tabs.forEach((t,i)=>t.setAttribute('aria-pressed',String(i===index)));$('#idea-form').hidden=!!index;$('#home-template-search').hidden=!index;$('#home-template-recommendations').hidden=!index;if(!index)return;if(!catalog)catalog=await(await fetch('/static/templates.json')).json();const names=['Scheduling Poll','Meeting Feedback Survey','Event Registration Form','General Event Feedback Survey'];const list=names.map(n=>catalog.find(t=>t.title===n)).filter(Boolean);$('#home-template-recommendations').innerHTML='<div class="row spread"><p>Recommended for <a href="/create/templates/?q=event">Meeting and event feedback</a></p><a href="/create/templates/">See all</a></div><div class="home-template-strip">'+list.map((t,i)=>`<button data-home-template="${i}" class="home-template-card"><span aria-hidden="true">${i%2?'▤':'▦'}</span><strong>${E(t.title)}</strong><p>${E(t.description)}</p></button>`).join('')+'</div>';bind('[data-home-template]',(_,el)=>openTemplate(list[Number(el.dataset.homeTemplate)]))}
 tabs.forEach((tab,i)=>tab.onclick=()=>show(i).catch(e=>toast(e.message)));$('#home-template-search').onsubmit=e=>{e.preventDefault();location.href='/create/templates/?'+new URLSearchParams(new FormData(e.target))};
}
document.addEventListener('click',e=>{for(const id of ['product-dropdown','account-dropdown']){const menu=$('#'+id),trigger=$('#'+(id==='product-dropdown'?'product-switcher':'account-menu'));if(menu&&!menu.contains(e.target)&&!trigger.contains(e.target)){menu.remove();trigger.setAttribute('aria-expanded','false')}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')for(const id of ['product-dropdown','account-dropdown'])$('#'+id)?.remove()});
